INSERT INTO `chr_classes_locale` (`ID`, `locale`, `Name_lang`, `NameMale_lang`, `NameFemale_lang`, `Description_lang`, `RoleInfoString_lang`, `DisabledString_lang`, `HyphenatedNameMale_lang`, `HyphenatedNameFemale_lang`, `VerifiedBuild`) VALUES
(4, 'esES', 'Pícaro', 'Pícaro', 'Pícara', 'Los pícaros ejercen de asesinos o exploradores, aunque otros van por libre. A menudo, se acercan con sigilo a sus enemigos o los atacan por la espalda para acabar con ellos rápidamente.', 'Función: |cffffffffDaño cuerpo a cuerpo|r', 'Debes elegir una raza diferente para ser de esta clase.', 'Pícaro', 'Pícara', 56647);
