INSERT INTO `chr_races_locale` (`ID`, `locale`, `Name_lang`, `NameFemale_lang`, `NameLowercase_lang`, `NameFemaleLowercase_lang`, `LoreName_lang`, `LoreNameFemale_lang`, `LoreNameLower_lang`, `LoreNameLowerFemale_lang`, `LoreDescription_lang`, `ShortName_lang`, `ShortNameFemale_lang`, `ShortNameLower_lang`, `ShortNameLowerFemale_lang`, `VerifiedBuild`) VALUES
(85, 'esES', 'Terráneo', 'Terránea', 'terráneo', 'terránea', 'Terráneo', '', 'terráneo', '', 'Los nuevos terráneos, recién liberados de los edictos que los constreñían, emergen con una curiosidad infinita para explorar el mundo y unirse a la Alianza.', 'Terráneos', '', 'terráneo', '', 56647),
(84, 'esES', 'Terráneo', 'Terránea', 'terráneo', 'terránea', 'Terráneo', '', 'terráneo', '', 'Los nuevos terráneos, recién liberados de los edictos que los constreñían, emergen con una curiosidad infinita para explorar el mundo y unirse a la Horda.', 'Terráneos', '', 'terráneo', '', 56647),
(36, 'esES', 'Orco Mag\'har', 'Orco Mag\'har', 'orco', 'orco', 'Mag\'har', '', 'Mag\'har', '', 'Los clanes de orcos incorruptos de Draenor, antaño rivales, se han unido ahora bajo el nombre Mag\'har.', 'Orco', '', 'orco', '', 56647);
