INSERT INTO `faction_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2640, 'esES', 'Brann Barbabronce', 'Compañero de las profundidades fiable', 56647),
(2600, 'esES', 'Los Hilos Cortados', 'El tumultuoso reinado de Ansurek no está exento de detractores. Los Hilos Cortados trabajan astuta y silenciosamente entre bastidores para desenredar el tapiz de la tiranía de su reina.', 56647),
(2596, 'esES', 'Los Hilos Cortados (baluarte)', 'El tumultuoso reinado de Ansurek no está exento de detractores. Los Hilos Cortados trabajan astuta y silenciosamente entre bastidores para desenredar el tapiz de la tiranía de su reina.', 56647),
(2606, 'esES', 'Las Cuencas Altas', 'Controla el comportamiento de las criaturas en las Cuencas Altas de la Ciudad Tejida.', 56647),
(2649, 'esES', 'El general (dechado)', 'Anub\'azal era uno de los líderes militares con mayor renombre de Azj-Kahet hasta que la reina Ansurek lo depuso para sustituirlo por uno de sus queridos Ascendidos. Esta afrenta no quedará impune.', 56647),
(2648, 'esES', 'La Tejedora (dechado)', 'La viuda Arak\'nai, antigua Tejedora Real, vigila su antiguo hogar con ojo crítico. Gracias a su red de tejerratas y espías, no hay secreto que se le escape.', 56647),
(2647, 'esES', 'El visir (dechado)', 'El ejecutor Nizrek goza de una de las posiciones más privilegiadas, pero también más peligrosas como consejero de la reina Ansurek. Por suerte, la nueva monarca aún no ha descubierto que dedica el resto de su tiempo a conspirar para acabar con su reinado.', 56647),
(2607, 'esES', 'El visir', 'El ejecutor Nizrek goza de una de las posiciones más privilegiadas, pero también más peligrosas como consejero de la reina Ansurek. Por suerte, la nueva monarca aún no ha descubierto que dedica el resto de su tiempo a conspirar para acabar con su reinado.', 56647),
(2605, 'esES', 'El general', 'Anub\'azal era uno de los líderes militares con mayor renombre de Azj-Kahet hasta que la reina Ansurek lo depuso para sustituirlo por uno de sus queridos Ascendidos. Esta afrenta no quedará impune.', 56647),
(2601, 'esES', 'La Tejedora', 'La viuda Arak\'nai, antigua Tejedora Real, vigila su antiguo hogar con ojo crítico. Gracias a su red de tejerratas y espías, no hay secreto que se le escape.', 56647);
