(28757, 'esES', 'Fase tres: Festín paranoico', 'Ansurek acoge un poder oscuro a medida que la paranoia se va apoderando de ella.', 56647),
(30060, 'esES', 'Sección 18', '$[!16\n\nEn dificultad mítica, los simulacros cósmicos estallan en una Nova en colapso si se colocan a menos de $461401s2 m entre sí.$]', 56647),
(30367, 'esES', 'Sección 25', '', 56647),
(30362, 'esES', 'Sección 83', '$[!15\n\nEn dificultad heroica, Anub\'arash debe pasar por 2 hebras de telaraña para quedar enredado.$]\n$[!16\n\nEn dificultad mítica, Anub\'arash debe pasar por 3 hebras de telaraña para quedar enredado.$]', 56647),
