INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(776, 'esES', 'Rylak espectral presto', '|cFFFFD200Montura antigua|r', 'Hasta los muertos necesitan transporte de vez en cuando.', 56647),
(2188, 'esES', 'Kah, Leyenda de las Zonas profundas', '|cFFFFD200Logro: |rPeces a raudales|n|cFFFFD200Categoría: |rPesca', '', 56647),
(2218, 'esES', 'Murciélago vil de Gladiador forjado', '|cFFFFD200Logro: |rGladiador: temporada 1 de The War Within|n|cFFFFD200Categoría: |rJugador contra jugador', 'Despertado de las cuevas en el campo de batalla, y blindado para la refriega.', 56647),
(2159, 'esES', 'Unidad de defensa mecanizada 1-11', '|cFFFFD200Tesoro: |rAlijo despertado|n|cFFFFD200Zona: |rCavernas Resonantes', 'Uno de los muchos mecatrajes que se diseñaron para proteger la máquina. Tras años de leal servicio, ya no es adecuado para el combate. Sin embargo, es un medio de transporte impresionante.', 56647),
(2209, 'esES', 'Morrolodo carmesí', '|cFFFFD200Vendedor: |rCerero Squick|n|cFFFFD200Zona: |rCavernas Resonantes|n|cFFFFD200Coste: |r8125|Hcurrency:2815|h|TInterface\\ICONS\\SPELL_AZERITE_ESSENCE14.BLP:0|t|h', 'La Asamblea de las Profundidades ha decidido dejarte usar uno de sus más leales morrolodos, la montura que usan con frecuencia los kóbolds.', 56647);
